delete from public.listening_clips where title_en in ('Lost Keys', 'A New Neighbour', 'Calling the Dentist', 'A Change of Plans', 'Choosing a Phone Plan', 'Instructions for a New Job', 'A Radio Tip on Saving Energy', 'Feedback After a Presentation', 'A Debate on School Uniforms');

insert into public.listening_clips (title_he, title_en, transcript_en, cefr_level, style, sort_order) values
  ('המפתחות שנעלמו', 'Lost Keys', 'Mom, have you seen my keys? I can''t find them anywhere. Did you look in your bag? Yes, twice. They''re not there. When did you last use them? Yesterday evening, when I came home from the gym. Then they''re probably in your jacket. Which jacket? The blue one. You wore it yesterday because it was cold. Let me check. Yes! Here they are, in the left pocket. Great. Now hurry, the bus leaves in ten minutes. Thanks, Mom. See you tonight!', 'A2', 'standard', 100),
  ('שכנים חדשים', 'A New Neighbour', 'Hi, I''m Dana. I just moved into the flat next door. Oh, welcome! I''m Yossi. When did you arrive? On Sunday. Everything is still in boxes. I know how that feels. Do you need anything? Actually, yes. Is there a supermarket near here? Yes, there''s a small one at the end of the street. It''s open until ten at night. And the big one is about fifteen minutes away by car. Thanks! And when is the rubbish collected? On Mondays and Thursdays, early in the morning. Good to know. Thanks for your help!', 'A2', 'standard', 101),
  ('טלפון למרפאת השיניים', 'Calling the Dentist', 'Good morning, Smile Dental Clinic. Hello, I''d like to make an appointment, please. I have a toothache. I''m sorry to hear that. Is it very bad? It started two days ago, and it hurts when I drink something cold. Okay. The doctor can see you tomorrow at eleven, or on Wednesday at four. Tomorrow at eleven is fine. Can I have your name, please? It''s Ron Peretz. Thank you, Ron. Please come ten minutes early and bring your ID card. See you tomorrow.', 'A2', 'standard', 102),
  ('שינוי בתוכניות', 'A Change of Plans', 'Hey, it''s Noa. I''m calling about Friday. I know we said we''d go to the beach, but the forecast says it''s going to be windy and maybe even rain in the afternoon. So I was thinking, what if we go to the new science museum in Holon instead? My cousin went last month and said the space exhibition is amazing. It opens at ten, and if we buy tickets online, they''re twenty percent cheaper. We could have lunch at that Italian place nearby and still be home by five. If the weather turns out fine, we can do the beach on Saturday morning. Let me know what you think. Text me tonight, because I need to book the tickets before tomorrow.', 'B1', 'standard', 103),
  ('בחירת חבילה סלולרית', 'Choosing a Phone Plan', 'So, which plan are you interested in? I''m not sure. I use my phone mostly for messages and maps, and I watch videos on the train. Then I''d recommend the basic plan with twenty gigabytes. It''s forty-nine shekels a month. Is twenty enough if I watch videos every day? Probably not. Video uses a lot of data. In that case, the unlimited plan is better. It''s sixty-nine shekels, and it includes calls abroad to thirty countries. Is there a contract? No, you can cancel at any time without paying anything extra. And if I join today, the first month is free. That sounds good. I''ll take the unlimited plan, then.', 'B1', 'standard', 104),
  ('הוראות ביום הראשון בעבודה', 'Instructions for a New Job', 'Welcome to your first day! Let me explain how things work here. Your shift starts at eight, but please arrive a few minutes early so you have time to change into your uniform. The lockers are next to the kitchen, and you''ll get your key from the office. You have a thirty-minute lunch break, usually around one, but check with your manager because it changes when we''re busy. If you''re sick, call the office before seven in the morning, not after, so we can find someone to replace you. And one more thing: phones stay in the locker during your shift. If there''s an emergency, your family can call the office number. Any questions so far?', 'B1', 'standard', 105),
  ('טיפ ברדיו על חיסכון בחשמל', 'A Radio Tip on Saving Energy', 'Welcome back. With the summer heat on its way, a lot of you have written in asking how to keep your electricity bill under control. So here''s what the experts told us. First, the air conditioner. Most people set it to around twenty degrees, but every degree lower adds roughly six percent to its energy use. Setting it to twenty-four or twenty-five keeps the room comfortable and saves a surprising amount over a month. Second, close the blinds during the hottest hours, especially on windows that face west. It sounds obvious, but a room that doesn''t heat up in the first place needs far less cooling. And finally, don''t leave devices on standby overnight. Individually they use very little, but together they can add up to around five percent of a household''s bill.', 'B2', 'standard', 106),
  ('משוב אחרי מצגת', 'Feedback After a Presentation', 'Have you got a minute? I wanted to give you some feedback on this morning''s presentation. Overall, it went really well. The client clearly liked the design, and your answer to the question about the budget was spot on. There are a couple of things I''d do differently next time, though. You spent almost ten minutes on the background, which they already knew from our email, so by the time we got to the actual proposal, some of them had started checking their phones. I''d cut that part down to two minutes at most. Also, a few of the slides had a lot of text. People end up reading instead of listening to you. Try keeping it to one main idea per slide. But honestly, these are small things. You came across as confident and well prepared.', 'B2', 'standard', 107),
  ('ויכוח על תלבושת אחידה', 'A Debate on School Uniforms', 'I think school uniforms make a lot of sense. They save parents money, and nobody gets judged for not wearing expensive brands. I see your point about money, but I''m not convinced it''s true in practice. Uniform shirts with the school logo often cost more than ordinary T-shirts, and kids still find ways to show off, with shoes, phones or bags. Fair enough, but at least it reduces the pressure every single morning. Teenagers spend a ridiculous amount of time deciding what to wear. Maybe, but choosing what to wear is also a way of expressing who you are. Taking that away at an age when you''re figuring out your identity doesn''t seem right to me. So what''s the alternative? A simple dress code, I''d say. No offensive slogans, nothing unsafe, and beyond that, let students decide for themselves.', 'B2', 'standard', 108);

insert into public.exercises (type, skill_area, listening_clip_id, cefr_level, content, sort_order)
select 'mcq'::exercise_type, 'listening'::skill_area, lc.id, lc.cefr_level, gen.content::jsonb, gen.sort_order
from public.listening_clips lc
join (values
  ('Lost Keys', '{"prompt":"When did the speaker last use the keys?","options":["This morning","Yesterday evening","Last weekend","An hour ago"],"correctIndex":1}', 2),
  ('Lost Keys', '{"prompt":"Where were the keys?","options":["In the bag","On the table","In the jacket pocket","In the car"],"correctIndex":2}', 3),
  ('Lost Keys', '{"prompt":"Why did the speaker wear the blue jacket yesterday?","options":["It was new","Mom asked","It was raining","It was cold"],"correctIndex":3}', 4),
  ('A New Neighbour', '{"prompt":"When did Dana move in?","options":["On Saturday","On Sunday","On Monday","On Thursday"],"correctIndex":1}', 2),
  ('A New Neighbour', '{"prompt":"Until what time is the small supermarket open?","options":["Eight","Nine","Ten","Eleven"],"correctIndex":2}', 3),
  ('A New Neighbour', '{"prompt":"When is the rubbish collected?","options":["On Fridays","Every day","On Sundays only","On Mondays and Thursdays"],"correctIndex":3}', 4),
  ('Calling the Dentist', '{"prompt":"When did the toothache start?","options":["Yesterday","Two days ago","Last week","This morning"],"correctIndex":1}', 2),
  ('Calling the Dentist', '{"prompt":"When is the appointment?","options":["Wednesday at four","Today at four","Tomorrow at eleven","Wednesday at eleven"],"correctIndex":2}', 3),
  ('Calling the Dentist', '{"prompt":"What should the patient bring?","options":["A letter from a doctor","Nothing","Money","An ID card"],"correctIndex":3}', 4),
  ('A Change of Plans', '{"prompt":"Why does Noa want to change the plan?","options":["The beach is closed","The weather may be bad","She is busy on Friday","The museum is free"],"correctIndex":1}', 2),
  ('A Change of Plans', '{"prompt":"What is the advantage of buying tickets online?","options":["You can come at any time","You don''t have to wait","They are cheaper","You get free lunch"],"correctIndex":2}', 3),
  ('A Change of Plans', '{"prompt":"Why should the listener text tonight?","options":["The cousin is waiting","The restaurant needs a booking","The museum closes early","Noa needs to book tickets before tomorrow"],"correctIndex":3}', 4),
  ('Choosing a Phone Plan', '{"prompt":"What does the customer use the phone for on the train?","options":["Games","Videos","Music","Calls"],"correctIndex":1}', 2),
  ('Choosing a Phone Plan', '{"prompt":"How much is the unlimited plan?","options":["Forty-nine shekels","Fifty-nine shekels","Sixty-nine shekels","Seventy-nine shekels"],"correctIndex":2}', 3),
  ('Choosing a Phone Plan', '{"prompt":"What happens if the customer joins today?","options":["They get extra data","They pay less forever","They get a new phone","The first month is free"],"correctIndex":3}', 4),
  ('Instructions for a New Job', '{"prompt":"Where are the lockers?","options":["Next to the office","Next to the kitchen","At the entrance","Upstairs"],"correctIndex":1}', 2),
  ('Instructions for a New Job', '{"prompt":"When should a sick worker call?","options":["After lunch","The day before","Before seven","At eight"],"correctIndex":2}', 3),
  ('Instructions for a New Job', '{"prompt":"What is the rule about phones?","options":["They can be used at lunch only","There is no rule","They must be turned off","They stay in the locker"],"correctIndex":3}', 4),
  ('A Radio Tip on Saving Energy', '{"prompt":"What happens with every degree lower on the air conditioner?","options":["Energy use drops","Energy use rises by about six percent","The room heats up","Nothing changes"],"correctIndex":1}', 2),
  ('A Radio Tip on Saving Energy', '{"prompt":"Which windows does the speaker mention especially?","options":["North-facing","East-facing","West-facing","South-facing"],"correctIndex":2}', 3),
  ('A Radio Tip on Saving Energy', '{"prompt":"What is said about devices on standby?","options":["They are dangerous","They should be replaced","They use nothing","Together they can be about five percent of the bill"],"correctIndex":3}', 4),
  ('Feedback After a Presentation', '{"prompt":"What part of the presentation went especially well?","options":["The background section","The answer about the budget","The slides with text","The timing"],"correctIndex":1}', 2),
  ('Feedback After a Presentation', '{"prompt":"Why does the manager suggest shortening the background?","options":["It was boring to prepare","The room was booked","The client already knew it","It had mistakes"],"correctIndex":2}', 3),
  ('Feedback After a Presentation', '{"prompt":"What is the advice about slides?","options":["Add more detail","Print them for the client","Use more pictures and no text","One main idea per slide"],"correctIndex":3}', 4),
  ('A Debate on School Uniforms', '{"prompt":"What is the first speaker''s main argument for uniforms?","options":["They look smart","They save money and reduce judgement","Teachers prefer them","They are required by law"],"correctIndex":1}', 2),
  ('A Debate on School Uniforms', '{"prompt":"Why does the second speaker doubt the money argument?","options":["Uniforms last for years","Schools give them for free","Uniforms with the logo can cost more","Parents never pay for clothes"],"correctIndex":2}', 3),
  ('A Debate on School Uniforms', '{"prompt":"What does the second speaker suggest instead?","options":["Uniforms only on special days","Letting parents vote","No rules at all","A simple dress code"],"correctIndex":3}', 4)
) as gen(title_en, content, sort_order)
  on lc.title_en = gen.title_en;

insert into public.exercises (type, skill_area, listening_clip_id, cefr_level, content, sort_order)
select 'dictation'::exercise_type, 'listening'::skill_area, lc.id, lc.cefr_level, gen.content::jsonb, 1
from public.listening_clips lc
join (values
  ('Lost Keys', '{"audioText":"When did you last use them?","correctAnswer":"When did you last use them?"}'),
  ('A New Neighbour', '{"audioText":"There''s a small one at the end of the street.","correctAnswer":"There''s a small one at the end of the street."}'),
  ('Calling the Dentist', '{"audioText":"Please come ten minutes early and bring your ID card.","correctAnswer":"Please come ten minutes early and bring your ID card."}'),
  ('A Change of Plans', '{"audioText":"If the weather turns out fine, we can do the beach on Saturday morning.","correctAnswer":"If the weather turns out fine, we can do the beach on Saturday morning."}'),
  ('Choosing a Phone Plan', '{"audioText":"You can cancel at any time without paying anything extra.","correctAnswer":"You can cancel at any time without paying anything extra."}'),
  ('Instructions for a New Job', '{"audioText":"Please arrive a few minutes early so you have time to change into your uniform.","correctAnswer":"Please arrive a few minutes early so you have time to change into your uniform."}'),
  ('A Radio Tip on Saving Energy', '{"audioText":"A room that doesn''t heat up in the first place needs far less cooling.","correctAnswer":"A room that doesn''t heat up in the first place needs far less cooling."}'),
  ('Feedback After a Presentation', '{"audioText":"People end up reading instead of listening to you.","correctAnswer":"People end up reading instead of listening to you."}'),
  ('A Debate on School Uniforms', '{"audioText":"Choosing what to wear is also a way of expressing who you are.","correctAnswer":"Choosing what to wear is also a way of expressing who you are."}')
) as gen(title_en, content)
  on lc.title_en = gen.title_en;

-- Check: clips from this seed, and their questions.
select
  (select count(*) from public.listening_clips where title_en in ('Lost Keys', 'A New Neighbour', 'Calling the Dentist', 'A Change of Plans', 'Choosing a Phone Plan', 'Instructions for a New Job', 'A Radio Tip on Saving Energy', 'Feedback After a Presentation', 'A Debate on School Uniforms')) as new_clips,
  (select count(*) from public.exercises e join public.listening_clips lc on lc.id = e.listening_clip_id
     where e.type = 'mcq' and lc.title_en in ('Lost Keys', 'A New Neighbour', 'Calling the Dentist', 'A Change of Plans', 'Choosing a Phone Plan', 'Instructions for a New Job', 'A Radio Tip on Saving Energy', 'Feedback After a Presentation', 'A Debate on School Uniforms')) as listening_questions;
